import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"A/B 槽位、安装与 OTA 升级","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/update-ota.md","filePath":"zh/manual/update-ota.md"}'),n={name:"zh/manual/update-ota.md"};function c(i,a,l,p,d,r){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="a-b-槽位、安装与-ota-升级" tabindex="-1">A/B 槽位、安装与 OTA 升级 <a class="header-anchor" href="#a-b-槽位、安装与-ota-升级" aria-label="Permalink to &quot;A/B 槽位、安装与 OTA 升级&quot;">​</a></h1><h2 id="a-b-方案" tabindex="-1">A/B 方案 <a class="header-anchor" href="#a-b-方案" aria-label="Permalink to &quot;A/B 方案&quot;">​</a></h2><p><code>kernel/ota/ota_ab.c</code> 维护两个槽位（A 和 B）以及一个启动标志：</p><ul><li>GRUB 读取标志并启动活动槽位；菜单提供强制槽位条目作为手动覆盖。</li><li>更新在您继续运行时安装到<em>非活动</em>槽位。</li><li>下次启动将切换到更新后的槽位；如果拒绝，<code>update rollback</code> 会切换回来。</li></ul><h2 id="安装到磁盘" tabindex="-1">安装到磁盘 <a class="header-anchor" href="#安装到磁盘" aria-label="Permalink to &quot;安装到磁盘&quot;">​</a></h2><p>从正在运行的 ISO 启动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dskstat                (pick a target disk, e.g. ata0)</span></span>
<span class="line"><span>oc&gt; install ata0           (partition + copy the running kernel +</span></span>
<span class="line"><span>                            GRUB boot files + /etc volume)</span></span></code></pre></div><p><code>install</code> 将 multiboot2 模块 <code>self</code>——即当前正在运行的内核 ELF——复制到磁盘，因此安装的系统始终与其安装程序匹配。<code>abdisk &lt;dev&gt;</code> 执行相同操作，但格式为 A/B 更新磁盘（两个槽位 + 标志；会销毁数据）。</p><p><code>abcfg</code> 显示这些命令写入的确切 grub.cfg 文件。</p><h2 id="检查更新" tabindex="-1">检查更新 <a class="header-anchor" href="#检查更新" aria-label="Permalink to &quot;检查更新&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; checkupdate            (reads the update URL from /etc/opencube.conf</span></span>
<span class="line"><span>                            - http or https - and parses the manifest)</span></span>
<span class="line"><span>oc&gt; config get update_url  (the configuration key it uses)</span></span></code></pre></div><p>清单是网站的 <code>update.json</code>：版本、构建、包 URL、包 SHA256、大小。</p><h2 id="应用更新" tabindex="-1">应用更新 <a class="header-anchor" href="#应用更新" aria-label="Permalink to &quot;应用更新&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; update download        (fetch the OTA package)</span></span>
<span class="line"><span>oc&gt; update verify          (SHA256 + signature check)</span></span>
<span class="line"><span>oc&gt; update install a       (install onto slot A/B - the inactive one)</span></span>
<span class="line"><span>oc&gt; reboot                 (boot the updated slot)</span></span></code></pre></div><p>OTA 包（<code>opencube-&lt;version&gt;-update.tar.gz</code>）携带新的内核 ELF 和一个清单。验证是密码学性质的：哈希加签名——任一项失败的包都会被拒绝。</p><h2 id="回滚" tabindex="-1">回滚 <a class="header-anchor" href="#回滚" aria-label="Permalink to &quot;回滚&quot;">​</a></h2><p>如果槽位在切换后行为异常：</p><ol><li>从 GRUB 菜单选择另一个槽位（强制条目），或</li><li>在运行中的系统内执行 <code>oc&gt; update rollback</code>。</li></ol><p><code>ab_partition_test</code> 在一个临时磁盘上测试槽位发现、标志和槽位切换，不会触碰您的真实启动磁盘。</p><h2 id="更新相关命令" tabindex="-1">更新相关命令 <a class="header-anchor" href="#更新相关命令" aria-label="Permalink to &quot;更新相关命令&quot;">​</a></h2><p><code>checkupdate</code>、<code>checkupdate_test</code>、<code>update</code>（上述流程）、<code>ab_partition_test</code>、<code>abcfg</code>、<code>abdisk</code>、<code>config</code>（更新 URL 键）。完整列表每条命令一页： <a href="./commands/">命令索引</a> - &quot;OTA 更新与 A/B 槽位&quot; 领域。</p><h2 id="内部机制" tabindex="-1">内部机制 <a class="header-anchor" href="#内部机制" aria-label="Permalink to &quot;内部机制&quot;">​</a></h2><p>有关标志如何存储、安装如何准备非活动槽位、以及与 GRUB 的启动标志握手机制，详见 <a href="./../internals/ota-ab.html">../internals/ota-ab.md</a>。</p>`,23)])])}const b=e(n,[["render",c]]);export{u as __pageData,b as default};
